using sv_3f470e312de347b0b216991a903908d6.Models;

namespace sv_3f470e312de347b0b216991a903908d6.Services;

public interface IRecipeService
{
    Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken);
}

public sealed class RecipeService : IRecipeService
{
    private static readonly Dictionary<int, List<Recipe>> SeedData = new()
    {
        [1] = new List<Recipe>
        {
            new(1, "Spaghetti Carbonara", "Classic Roman pasta with egg, pecorino, guanciale, and black pepper.", 30),
            new(2, "Margherita Pizza", "Simple pizza with tomato sauce, fresh mozzarella, and basil.", 45),
            new(3, "Risotto al Funghi", "Creamy Arborio rice with mixed wild mushrooms and Parmigiano.", 40),
            new(4, "Tiramisu", "Layered dessert of espresso-soaked ladyfingers and mascarpone cream.", 25),
        },
        [2] = new List<Recipe>
        {
            new(5, "Chicken Tikka Masala", "Marinated chicken in a creamy spiced tomato sauce.", 50),
            new(6, "Palak Paneer", "Fresh spinach cooked with cubes of paneer cheese and aromatic spices.", 35),
            new(7, "Biryani", "Fragrant basmati rice layered with spiced meat and caramelized onions.", 60),
            new(8, "Samosa", "Crispy pastry filled with spiced potatoes and peas.", 45),
        },
        [3] = new List<Recipe>
        {
            new(9, "Tacos al Pastor", "Spit-grilled pork with pineapple, onion, and cilantro on corn tortillas.", 40),
            new(10, "Guacamole", "Fresh avocado dip with lime, cilantro, onion, and jalapeño.", 10),
            new(11, "Enchiladas Verdes", "Corn tortillas filled with chicken, topped with tangy green salsa.", 35),
            new(12, "Churros", "Fried dough sticks coated in cinnamon sugar, served with chocolate sauce.", 30),
        },
    };

    public async Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken)
    {
        // Simulate a slow backend API call
        await Task.Delay(2000, cancellationToken);

        if (SeedData.TryGetValue(cuisineId, out var recipes))
        {
            return recipes;
        }

        return new List<Recipe>();
    }
}

